@@ -0,0 +1,27 @@
+import { randomBytes } from 'node:crypto';
+import { describe, expect, it } from 'vitest';
+import { hashPassword, passwordMatches, verifyPassword } from './passwords';
+
+// Made up for each run, so no password is written here.
+const password = randomBytes(18).toString('base64url');
+
+describe('passwords', () => {
+  it('stores Argon2id hashes (19 MiB, 2 passes, 1 thread), each with its own salt', async () => {
+    const first = await hashPassword(password);
+    expect(first).toMatch(/^\$argon2id\$v=19\$m=19456,t=2,p=1\$/);
+    expect(first).not.toContain(password);
+    expect(await hashPassword(password)).not.toBe(first);
+  });
+
+  it('checks a password against its hash', async () => {
+    const stored = await hashPassword(password);
+    expect(await verifyPassword(stored, password)).toBe(true);
+    expect(await verifyPassword(stored, `${password}x`)).toBe(false);
+    expect(await verifyPassword('not a hash', password)).toBe(false);
+  });
+
+  it('answers false without a stored hash, after checking against a throwaway one', async () => {
+    expect(await passwordMatches(null, password)).toBe(false);
+    expect(await passwordMatches(await hashPassword(password), password)).toBe(true);
+  });
+});
diff --git a/apps/server/src/features/auth/passwords.ts b/apps/server/src/features/auth/passwords.ts
new file mode 100644
index 0000000..10e836b
--- /dev/null
+++ b/apps/server/src/features/auth/passwords.ts
@@ -0,0 +1,52 @@
+import { randomBytes } from 'node:crypto';
+import { hash, verify } from '@node-rs/argon2';
+
+/**
+ * Argon2id (the library's default algorithm) with OWASP's minimum settings: 19 MiB of memory, 2
+ * passes and 1 thread. Each hash stores its settings and its own random salt, so the settings can
+ * go up later without breaking older hashes.
+ */
+const ARGON2_OPTIONS = { memoryCost: 19_456, timeCost: 2, parallelism: 1, outputLen: 32 };
+
+/** An Argon2id hash for `users.password_hash`. */
+export function hashPassword(password: string): Promise<string> {
+  return hash(password, ARGON2_OPTIONS);
+}
+
+/** Whether `password` matches the stored hash. False, never an error, for a damaged hash. */
+export async function verifyPassword(storedHash: string, password: string): Promise<boolean> {
+  try {
+    return await verify(storedHash, password);
+  } catch {
+    return false;
+  }
+}
+
+let throwawayHash: Promise<string> | undefined;
+
+/**
+ * The throwaway hash `passwordMatches` checks when there's no stored one. Made once: call it at
+ * start-up, so the first sign-in with an unknown email doesn't take longer than the others. If
+ * making it fails, the next call tries again.
+ */
+export function makeThrowawayHash(): Promise<string> {
+  throwawayHash ??= hashPassword(randomBytes(32).toString('base64url')).catch((error: unknown) => {
+    throwawayHash = undefined;
+    throw error;
+  });
+  return throwawayHash;
+}
+
+/**
+ * For sign-in. Without a stored hash (an unknown email, or an account that has no password yet) it
+ * still checks the password once, against the throwaway hash, so the answer takes as long either
+ * way and doesn't show which emails have accounts.
+ */
+export async function passwordMatches(
+  storedHash: string | null,
+  password: string,
+): Promise<boolean> {
+  if (storedHash !== null) return verifyPassword(storedHash, password);
+  await verifyPassword(await makeThrowawayHash(), password);
+  return false;
+}
