+function send(app: FastifyInstance, browser: Browser, options: InjectOptions) {
+  const cookie = Object.entries(browser.cookies)
+    .map(([name, value]) => `${name}=${value}`)
+    .join('; ');
+  return app.inject({
+    ...options,
+    headers: { cookie, [CSRF_HEADER]: browser.csrf, ...options.headers },
+  });
+}
