+      .insert(users)
+      .values({
+        email: normalizeEmail(input.email),
+        name: input.name,
+        passwordHash,
+        isSiteAdmin: input.isSiteAdmin ?? false,
+        mustChangePassword: input.mustChangePassword ?? false,
+      })
+      .returning(accountColumns);
