+  });
+
+  afterAll(async () => {
+    await test?.close();
+  });
+
+  const signIn = (email: string, password: string, browser: Browser = signedOut()) =>
+    send(app, browser, { method: 'POST', url: '/api/auth/sign-in', payload: { email, password } });
